//! The section and the help text of each setting, for the settings panel
//! of each app. Made by tools/settings_doc.py from src/settings.zig.
//! Do not edit by hand. A test in src/app/setting_info.zig checks that each
//! setting has an entry.

pub const Meta = struct {
    name: []const u8,
    section: []const u8,
    doc: []const u8,
};

pub const all = [_]Meta{
    .{ .name = "machine.name", .section = "Printer", .doc = "The name of the printer, for the G-code header." },
    .{ .name = "machine.model", .section = "Printer", .doc = "The id of the printer model in the printer library, for example \"creality-ender-3-v2\". The 3D view shows the bed model of this printer. Empty: the view shows the bed as a grid." },
    .{ .name = "machine.bed_size_x", .section = "Bed", .doc = "The size of the bed in X." },
    .{ .name = "machine.bed_size_y", .section = "Bed", .doc = "The size of the bed in Y." },
    .{ .name = "machine.origin_x", .section = "Bed", .doc = "The G-code X of the front left corner of the bed. The slicer places parts in bed coordinates (0, 0 at the front left corner) and adds this to each X in the G-code. Most printers: 0. A printer with its origin at the bed center: minus half the bed width." },
    .{ .name = "machine.origin_y", .section = "Bed", .doc = "The G-code Y of the front left corner of the bed. See `origin_x`." },
    .{ .name = "machine.max_height", .section = "Bed", .doc = "The highest part that the printer can make." },
    .{ .name = "machine.bed_type", .section = "Bed", .doc = "The build plate on the bed, for a printer with plates that change (Bambu Lab): the start G-code of the printer uses it ({curr_bed_type}), and the printer checks it against the plate that it sees." },
    .{ .name = "machine.nozzle_diameter", .section = "Nozzle", .doc = "The diameter of the nozzle hole. The default line width comes from it." },
    .{ .name = "machine.nozzle_type", .section = "Nozzle", .doc = "The material of the nozzle. A Bambu Lab printer checks it against the nozzle that it has (the file names it), and a hard filament (with carbon or glass fiber) needs hardened steel or tungsten carbide." },
    .{ .name = "machine.nozzle_flow", .section = "Nozzle", .doc = "The flow of the hot end: `standard`, or `high_flow` (a longer melt zone). A Bambu Lab printer checks it against its nozzle." },
    .{ .name = "machine.nozzle_tip_radius", .section = "Nozzle", .doc = "The radius of the flat face at the tip of the nozzle, around the hole. A common brass nozzle has a face about 1 mm across. Slope smoothing uses it to keep the nozzle off the layer that it just printed." },
    .{ .name = "machine.nozzle_cone_angle", .section = "Nozzle", .doc = "The angle between the axis of the nozzle and the side of its cone, in degrees. Slope smoothing uses it with `nozzle_tip_radius`." },
    .{ .name = "machine.chamber_temp", .section = "Chamber and fans", .doc = "The temperature of the air around the print, in °C: the room for an open printer, about 35 to 45 in a closed box with no heater, or the set point of a heated chamber. The simulated print cools the plastic toward it." },
    .{ .name = "machine.part_fan_air", .section = "Chamber and fans", .doc = "The speed of the air of the part cooling fans at full speed where the plastic leaves the nozzle, in m/s, of all the fans together. The simulated print cools the plastic with it. About 5 to 10 for a radial blower and a duct." },
    .{ .name = "machine.max_speed", .section = "Motion", .doc = "The maximum speed of the print head in X and Y." },
    .{ .name = "machine.travel_speed", .section = "Motion", .doc = "The speed of travel moves (moves with no extrusion)." },
    .{ .name = "machine.first_layer_travel_speed", .section = "Motion", .doc = "The speed of the travel moves of the first layer, in mm/s. A slower travel does not pull the new lines off the bed. 0: `travel_speed`. As \"Initial Layer Travel Speed\" in Cura and \"Initial layer travel speed\" in OrcaSlicer." },
    .{ .name = "machine.max_z_speed", .section = "Motion", .doc = "The speed of Z moves at each layer change." },
    .{ .name = "machine.max_z_accel", .section = "Motion", .doc = "The acceleration of Z moves (the layer change and the z hop), in mm/s². Only the time estimate uses it." },
    .{ .name = "machine.hour_rate", .section = "Motion", .doc = "The cost of one hour of this printer, in your currency: the power, the wear, and the time of the machine. A print costs its hours times this, and its filament. 0: only the filament counts." },
    .{ .name = "machine.max_accel", .section = "Motion", .doc = "The acceleration of the print head in X and Y, in mm/s². The time estimate uses it, and it is the acceleration of each feature that has no acceleration of its own (0 in `outer_wall_accel` and the others)." },
    .{ .name = "machine.corner_speed", .section = "Motion", .doc = "The speed at which the head turns a corner with no stop (jerk in Marlin, square corner velocity in Klipper), in mm/s. The time estimate uses it." },
    .{ .name = "machine.kinematics", .section = "Motion", .doc = "How the motors move the head, for the time estimate. `cartesian`: a motor for X and one for Y (also a bed slinger, which moves the bed on Y). `corexy`: two motors, A = X + Y and B = X - Y, both on the frame. With per-axis limits (`max_accel_x` and the others) and Marlin, the limits of a CoreXY apply to its motors: a diagonal move turns one motor at 1.41 times the speed of the head." },
    .{ .name = "machine.max_accel_x", .section = "Motion", .doc = "The acceleration limit of the X axis (of motor A on a CoreXY with Marlin), in mm/s², as the firmware has it (M201 X). 0: `max_accel`. Klipper has one limit for all directions: leave it at 0." },
    .{ .name = "machine.max_accel_y", .section = "Motion", .doc = "The acceleration limit of the Y axis (of motor B on a CoreXY with Marlin), in mm/s² (M201 Y). A bed slinger moves the bed on Y and has a lower limit. 0: `max_accel`." },
    .{ .name = "machine.max_speed_x", .section = "Motion", .doc = "The speed limit of the X axis (M203 X), in mm/s. 0: `max_speed`." },
    .{ .name = "machine.max_speed_y", .section = "Motion", .doc = "The speed limit of the Y axis (M203 Y), in mm/s. 0: `max_speed`." },
    .{ .name = "machine.accel_control", .section = "Motion", .doc = "Write acceleration commands in the G-code: the acceleration of each feature (`outer_wall_accel` and the others), and the corner speed at the start. Off: the printer uses its own values; the time estimate still uses `max_accel` and `corner_speed`." },
    .{ .name = "machine.gcode_flavor", .section = "Motion", .doc = "The G-code dialect of the acceleration commands. `marlin`: M204 S and M205 X Y. `klipper`: SET_VELOCITY_LIMIT ACCEL and SQUARE_CORNER_VELOCITY. `reprap` (RepRapFirmware): M204 P T and M566 X Y. `repetier`: M201 X Y and M207 X." },
    .{ .name = "machine.outer_wall_accel", .section = "Acceleration", .doc = "The acceleration of the outer wall, in mm/s². A lower value gives a cleaner surface. 0: `max_accel`. The G-code has it only with `accel_control`. Each printer has its own value." },
    .{ .name = "machine.inner_wall_accel", .section = "Acceleration", .doc = "The acceleration of the inner walls and the skirt, in mm/s². 0: `max_accel`." },
    .{ .name = "machine.skin_accel", .section = "Acceleration", .doc = "The acceleration of the skin, in mm/s². The bridges, the ironing, and the support interface use it too. 0: `max_accel`." },
    .{ .name = "machine.infill_accel", .section = "Acceleration", .doc = "The acceleration of the sparse infill and the support, in mm/s². 0: `max_accel`." },
    .{ .name = "machine.travel_accel", .section = "Acceleration", .doc = "The acceleration of travel moves, in mm/s². 0: `max_accel`." },
    .{ .name = "machine.first_layer_accel", .section = "Acceleration", .doc = "The acceleration of all lines on the first layer, in mm/s². 0: the acceleration of each feature." },
    .{ .name = "machine.extruder", .section = "Extruder", .doc = "The extruder type. `direct`: the motor is on the print head. `bowden`: the motor pushes the filament through a long tube." },
    .{ .name = "machine.retract_length", .section = "Extruder", .doc = "The retraction length of this extruder. A bowden extruder needs more." },
    .{ .name = "machine.retract_speed", .section = "Extruder", .doc = "The speed of the filament during a retraction." },
    .{ .name = "machine.retract_min_travel", .section = "Travel retraction", .doc = "Travel moves shorter than this do not retract. Each printer has its own value (Bambu Studio: 1 mm)." },
    .{ .name = "machine.z_hop", .section = "Travel retraction", .doc = "Lift the nozzle by this distance during a travel move with a retraction, in mm. 0 turns it off. The nozzle then does not drag over the printed lines (the tops of the support too)." },
    .{ .name = "machine.z_hop_only_crossing", .section = "Travel retraction", .doc = "Lift the nozzle (`z_hop`) only for a travel that leaves the part or crosses an edge of the layer (a hole), and for a travel to or from the support. A travel in a straight line inside the part (it retracts because it is longer than `combing_max_distance`) does not lift. Off: each travel with a retraction lifts." },
    .{ .name = "machine.retract_wipe", .section = "Travel retraction", .doc = "A retraction before a travel that leaves the part moves the nozzle on a small circle inside the part while the filament pulls back: the plastic that oozes goes inside, and not onto the surface or into a string. The circle stays clear of the outer wall by half a line width. With no room for it (a thin part, the support), the nozzle moves back along the line that it printed last. A travel that stays inside the part has no wipe." },
    .{ .name = "machine.retract_wipe_distance", .section = "Travel retraction", .doc = "The length of the wipe (`retract_wipe`), in mm: the length of the circle, or of the move back along the last line. 0: 1.9 mm (a circle of 0.4 mm radius)." },
    .{ .name = "machine.retract_layer_change", .section = "Travel retraction", .doc = "Retract at each layer change. Off: the travel to the first path of the layer retracts by the rules of the other travels (combing). Off by default, as in Cura." },
    .{ .name = "machine.filament_change", .section = "Filament change", .doc = "How the printer changes to another filament of the plate. `pause`: one filament path; the print pauses (M600) and you change the filament by hand. `tool`: a unit that feeds many filaments (a Bambu Lab AMS, a Prusa MMU) changes it with a tool change (T0, T1, and on)." },
    .{ .name = "machine.nozzles", .section = "Filament change", .doc = "The number of nozzles of the printer, 1 to 16. Each nozzle has its own hot end, and each filament prints with its own nozzle (`filament.nozzle`). Examples: 2 on the Bambu Lab X2D and H2D and on an IDEX printer, 5 on a Prusa XL 5T, 8 on a CORE One INDX 8T. The first nozzle has the settings of the Nozzle section. Each other nozzle has a section of its own (`nozzle.k.diameter` and the others), with the values of the first nozzle as defaults." },
    .{ .name = "machine.tool_numbers", .section = "Filament change", .doc = "The number n of a tool change command Tn. `filament`: the filament (from 0). A unit that feeds many filaments (a Bambu Lab AMS, a Prusa MMU) and the Bambu Lab X2D and H2D use it. `nozzle`: the nozzle of the filament (from 0), for a printer with a hot end for each filament (a tool changer, an IDEX printer). Two filaments on one nozzle then change with a pause (M600)." },
    .{ .name = "machine.nozzle1_max_x", .section = "Filament change", .doc = "The right edge of the area that the first nozzle reaches, in bed X (mm). The left nozzle of the H2D stops 25 mm from the right side. 0: the whole bed." },
    .{ .name = "machine.nozzle1_max_height", .section = "Filament change", .doc = "The highest z that the first nozzle reaches (mm). 0: `max_height`." },
    .{ .name = "machine.standby_delta", .section = "Filament change", .doc = "The temperature of a nozzle that waits for its next filament on a printer with more than one nozzle, in °C, as a change from the print temperature of its filament: -110 waits 110 °C below it. 0: the nozzle keeps its temperature. A filament with a `standby_temp` waits at that temperature. The next nozzle heats again before its first line. As \"Temperature variation\" of the ooze prevention in PrusaSlicer (standby_temperature_delta). A Bambu Lab X2D or H2D waits 10 °C below, as in Bambu Studio." },
    .{ .name = "machine.preheat_time", .section = "Filament change", .doc = "The time before a change to another nozzle at which that nozzle heats to its print temperature, in seconds. It is then hot, or almost hot, at the change. 0: it heats at the change. As \"Preheat time\" in OrcaSlicer. Only a change in the middle of a layer gets a preheat." },
    .{ .name = "machine.change_gcode", .section = "Filament change", .doc = "The text of a filament change. Empty: zslice writes the command of the G-code flavor (M600 for a pause, Tn for a tool change). The variables of Bambu Studio and PrusaSlicer work here: {next_extruder}, {previous_extruder}, [next_filament_id], [flush_length], [new_filament_temp], [old_filament_temp], {layer_z}, {max_layer_z}, and {toolchange_count}." },
    .{ .name = "machine.change_time", .section = "Filament change", .doc = "The time of one filament change, in seconds, for the time estimate: the cut, the unload, the load, and the flush. A pause counts this time too, but the real time depends on you." },
    .{ .name = "machine.flush_volume", .section = "Filament change", .doc = "The plastic (mm³) that the nozzle flushes after a change to a filament of the same color. A change from a dark color to a light color flushes up to 5 times more (see `project.flush_multiplier`). A pause flushes nothing: you push the new filament through by hand." },
    .{ .name = "machine.thumbnails", .section = "G-code", .doc = "The pictures of the print at the top of the G-code, for the screen of the printer: sizes in pixels, as \"300x300,32x32\" (PNG, the form of PrusaSlicer and Klipper). Empty: none." },
    .{ .name = "machine.label_objects", .section = "G-code", .doc = "Label each part in the G-code, so the printer can skip a part that fails and print the others: EXCLUDE_OBJECT_DEFINE, _START, and _END on Klipper (it needs [exclude_object] in printer.cfg), and M486 on Marlin and RepRapFirmware. Off by default." },
    .{ .name = "machine.clearance_radius", .section = "Head clearance", .doc = "The radius of a cylinder around the nozzle that holds the print head (the hot end, the fan ducts, the probe), in mm. With `project.print_sequence = by_object`, the parts keep this distance from each other, so the head does not hit a part that it printed before. As \"extruder_clearance_radius\" in PrusaSlicer and OrcaSlicer." },
    .{ .name = "machine.clearance_height", .section = "Head clearance", .doc = "The height from the tip of the nozzle to the lowest part of the gantry (the X axis rods or the frame of the head), in mm. With `project.print_sequence = by_object`, only the last part can be higher: the gantry passes over the parts before it. As \"extruder_clearance_height\" in PrusaSlicer and \"extruder_clearance_height_to_rod\" in OrcaSlicer." },
    .{ .name = "machine.start_gcode", .section = "Head clearance", .doc = "The text before the print. These variables are replaced: {nozzle_temp}, {first_layer_nozzle_temp}, {bed_temp}, {standby_temp}, {layer_height}, {first_layer_height}, {first_layer_speed} (mm/s), {nozzle_diameter}, {filament_diameter}, {filament_name}, {machine_name}, and {job_name}. The variables and the expressions of Cura, PrusaSlicer, OrcaSlicer, and Bambu Studio also work. A line with a variable that has no value becomes a comment. If the text does not heat the nozzle or the bed, zslice heats them before it." },
    .{ .name = "machine.end_gcode", .section = "Head clearance", .doc = "The text after the print. The same values as in `start_gcode` are replaced." },
    .{ .name = "filament.name", .section = "Filament", .doc = "The name of the filament, for the G-code header." },
    .{ .name = "filament.material", .section = "Filament", .doc = "The type of the plastic, for example \"PLA\", \"PETG\", \"ABS\", or \"TPU\". The Filament menu lists the rolls of this type." },
    .{ .name = "filament.color", .section = "Filament", .doc = "The color of the filament, as \"#rrggbb\". The 3D view draws the print in this color." },
    .{ .name = "filament.nozzle", .section = "Filament", .doc = "The nozzle of this filament on a printer with more than one nozzle (`machine.nozzles`), from 0: 0 is the first (main) nozzle, 1 the second, and on. On the X2D, the AMS feeds the main nozzle, and the external spool feeds the second one. On a tool changer, the nozzle is the tool (T0, T1, and on). A printer with one nozzle: 0. A nozzle that the printer does not have prints on the first nozzle, and the Check tells it." },
    .{ .name = "filament.diameter", .section = "Filament", .doc = "The diameter of the filament." },
    .{ .name = "filament.density", .section = "Filament", .doc = "g/cm^3. For the filament weight in the statistics." },
    .{ .name = "filament.price_per_kg", .section = "Filament", .doc = "The price of one kilogram of this filament, in your currency. For the cost of a print (the filament weight times this price)." },
    .{ .name = "filament.nozzle_temp", .section = "Temperatures", .doc = "The nozzle temperature from the second layer." },
    .{ .name = "filament.first_layer_nozzle_temp", .section = "Temperatures", .doc = "The nozzle temperature on the first layer." },
    .{ .name = "filament.bed_temp", .section = "Temperatures", .doc = "The bed temperature." },
    .{ .name = "filament.first_layer_bed_temp", .section = "Temperatures", .doc = "The bed temperature on the first layer. From the second layer, the bed goes to `bed_temp` (M140, no wait). 0: `bed_temp` on all layers. As \"Build Plate Temperature Initial Layer\" in Cura and \"Initial layer\" bed temperature in OrcaSlicer." },
    .{ .name = "filament.max_flow", .section = "Flow", .doc = "The maximum plastic flow that the hot end melts with this filament. This limits the speed of wide and tall lines." },
    .{ .name = "filament.flow_ratio", .section = "Flow", .doc = "A multiplier for all extrusion, to calibrate the flow." },
    .{ .name = "filament.pressure_advance", .section = "Flow", .doc = "The pressure advance of this filament, in seconds: the firmware pushes the filament ahead of a speed change by this time. zslice writes it after the start G-code (M900 K on Marlin, SET_PRESSURE_ADVANCE on Klipper, M572 on RepRapFirmware). 0: no command, so the value of the firmware stays. As \"Pressure advance\" in OrcaSlicer (`enable_pressure_advance` and `pressure_advance`)." },
    .{ .name = "filament.fan_speed", .section = "Cooling", .doc = "The part cooling fan speed, as a ratio." },
    .{ .name = "filament.fan_off_layers", .section = "Cooling", .doc = "The fan is off for this number of layers at the start." },
    .{ .name = "filament.fan_ramp_layers", .section = "Cooling", .doc = "After the layers with the fan off, the fan speed goes up in steps over this number of layers: layer k of the ramp (from 1) gets k / (ramp + 1) of the fan speed. 0: full speed at once." },
    .{ .name = "filament.fan_max_speed", .section = "Cooling", .doc = "The fan speed on short layers, as a ratio. See `fan_boost_time`." },
    .{ .name = "filament.fan_boost_time", .section = "Cooling", .doc = "A layer that takes less time than this (s) gets the fan at `fan_max_speed`." },
    .{ .name = "filament.min_layer_time", .section = "Cooling", .doc = "The shortest time (s) for one layer. A layer that takes less time prints slower, so that the plastic below has time to cool." },
    .{ .name = "filament.min_speed", .section = "Cooling", .doc = "The lowest print speed (mm/s) for the slow-down of `min_layer_time`." },
    .{ .name = "filament.cooling_mode", .section = "Cooling", .doc = "How a layer that takes less than `min_layer_time` gets its time to cool. `slow_down`: it prints slower. `lap`: it prints at the planned speed; then the nozzle goes up 1 mm and moves around the layer with the fan at full until the time is over, so the air blows on the new plastic. The lap keeps the planned speed of the walls." },
    .{ .name = "filament.standby_temp", .section = "Cooling", .doc = "A lower nozzle temperature for waits, for example while the printer probes the bed. The start G-code can use it as {standby_temp}. 0 is off." },
    .{ .name = "filament.shrinkage_xy", .section = "Size compensation", .doc = "The part is printed larger by this ratio in X and Y, because the plastic shrinks as it cools. Example: 1.003 for 0.3 % shrinkage." },
    .{ .name = "filament.shrinkage_z", .section = "Size compensation", .doc = "The part is printed taller by this ratio, for shrinkage in Z." },
    .{ .name = "filament.xy_offset", .section = "Size compensation", .doc = "Moves all outlines out by this distance (in if negative). Use it if parts come out too large or too small by a fixed amount." },
    .{ .name = "filament.hole_xy_offset", .section = "Size compensation", .doc = "Moves the edges of holes by this distance. A positive value makes holes larger. It adds to `xy_offset`, which makes holes smaller when it is positive. Holes often come out too small." },
    .{ .name = "filament.retract_ratio", .section = "Retraction", .doc = "A multiplier for the retraction length of the machine. Soft filament needs less." },
    .{ .name = "filament.start_gcode", .section = "G-code", .doc = "G-code after the start G-code of the machine, for this filament. The variables of the start G-code work here. Empty: none. As \"Filament start G-code\" in OrcaSlicer and PrusaSlicer." },
    .{ .name = "filament.end_gcode", .section = "G-code", .doc = "G-code before the end G-code of the machine, for this filament. Empty: none. As \"Filament end G-code\" in OrcaSlicer and PrusaSlicer." },
    .{ .name = "project.layer_height", .section = "Layers", .doc = "The height of each layer after the first. A smaller value gives a smoother surface and a longer print." },
    .{ .name = "project.first_layer_height", .section = "Layers", .doc = "The height of the first layer. A thicker first layer sticks to the bed better." },
    .{ .name = "project.line_width", .section = "Lines", .doc = "The line width. 0 uses 1.1 x the nozzle diameter." },
    .{ .name = "project.first_layer_line_width", .section = "Lines", .doc = "The line width on the first layer. 0 uses 1.25 x the nozzle diameter." },
    .{ .name = "project.wall_count", .section = "Walls", .doc = "The number of walls (loops) around the outline of each layer." },
    .{ .name = "project.wall_thickness", .section = "Walls", .doc = "The thickness of the walls, in mm, as in Cura: the wall count is this thickness divided by the line width, rounded (at least 1). 0: use `wall_count`." },
    .{ .name = "project.wall_order", .section = "Walls", .doc = "The order of the walls of each island. `inner_first`: the inner walls from the inside out, then the outer wall. The outer wall then lies against plastic, and an overhang prints better. `outer_first`: the outer wall first, then the inner walls from the outside in. The outer surface is then more exact (a better fit of holes and of parts that join), but an overhang can curl." },
    .{ .name = "project.alternate_extra_wall", .section = "Walls", .doc = "One more wall on each odd layer (layers 1, 3, 5, and so on). The walls of two layers then interlock with the infill, and the part is stronger across its layers. Off by default." },
    .{ .name = "project.overhang_wall_speed", .section = "Walls", .doc = "The speed of the parts of a wall that hang over air, as a ratio of the speed of the wall. A slower overhang has more time to cool, so it curls less. 1: the speed of the wall. A wall that hangs a whole line over air prints as a bridge (see `bridges`)." },
    .{ .name = "project.overhang_wall_fan", .section = "Walls", .doc = "The fan while a wall overhang prints, from 0 to 1. The fan does not go below the fan of the layer. 0: the fan of the layer." },
    .{ .name = "project.overhang_wall_threshold", .section = "Walls", .doc = "How far a wall must hang over air to print as an overhang (see `overhang_wall_speed`): the part of its line width that is outside the layer below, from 0 to 1. With a 0.2 mm layer and a 0.44 mm line, 0.5 is a slope of about 48 degrees." },
    .{ .name = "project.fuzzy_skin", .section = "Walls", .doc = "A rough surface: the nozzle moves to a random side along the outer wall, so the surface looks fuzzy and hides the layer lines and the seam. `off`: a smooth wall. `outer_wall`: each outer wall, the holes too. `outside`: only the outside of each part, and not its holes (a hole keeps its size). The first layer stays smooth." },
    .{ .name = "project.fuzzy_skin_thickness", .section = "Walls", .doc = "Fuzzy skin: the width of the band of the random points, in mm. A point goes up to half of it to the outside or to the inside of the wall. Keep it below the line width." },
    .{ .name = "project.fuzzy_skin_point_distance", .section = "Walls", .doc = "Fuzzy skin: the mean distance between the random points, in mm." },
    .{ .name = "project.spiral_vase", .section = "Walls", .doc = "Spiral vase mode: after the bottom layers, each layer prints only the outer wall of the part, and the nozzle rises along it, so the wall is one spiral with no seam. The part prints as a vase: no top, no infill, no inner walls, no holes. For a part with one outline on each layer. The bottom layers (`bottom_thickness`) print as usual." },
    .{ .name = "project.polyholes", .section = "Walls", .doc = "Polyholes: each round hole of a layer becomes a polygon with few sides (two for each mm of its diameter, at least 3), whose inner circle is the hole. A printed round hole shrinks, because each short segment of its wall cuts the corner; the flat sides of a polyhole print to size, so a pin or a screw fits. The method of nophead. Off by default." },
    .{ .name = "project.thin_walls", .section = "Walls", .doc = "Print parts of the outline that are thinner than one line width (a thin fin, a sheet, a label): a loop inside each thin part, with a narrower line, so that its two sides fill the thickness. Without it, these parts print nothing. Off by default." },
    .{ .name = "project.seam", .section = "Walls", .doc = "Where each wall loop starts and ends (the seam). `hidden`: at the point where the seam is hardest to see: an inside corner first, then an outside corner, toward the back, and not where the wall hangs over air; similar layers pick the same point, so the seam is one clean line. `sharpest`: in the deepest inside corner, or else in the sharpest outside corner, or else at the rear. `rear`: at the back of the part (the largest y), in one straight line. `nearest`: at the point nearest to the nozzle, which is the fastest. `random`: at a different point on each layer, so that no seam line shows." },
    .{ .name = "project.seam_corner", .section = "Walls", .doc = "The corners that the `sharpest` seam looks for, as \"Seam Corner Preference\" in Cura. `auto`: the zslice score (an inside corner, or else the sharpest outside corner). `inner`: inside corners, the sharper the better. `outer`: outside corners. `any`: the sharpest corner of either kind. `weighted`: any corner, but an inside corner counts twice. `none`: no corner, so the seam goes to the back right. With the other kinds of seam it has no effect." },
    .{ .name = "project.wall_generator", .section = "Walls", .doc = "The method that makes the walls. `classic`: each wall is the outline moved in by a whole number of line widths, with one line width. `arachne`: the walls follow the center lines of the part, and the width of each line changes along it, so that a whole number of lines fills the part. A part thinner than two lines gets one line in its middle, so `thin_walls` has no effect. This is the method of Cura and the other open source slicers." },
    .{ .name = "project.min_wall_line_width", .section = "Walls", .doc = "Arachne: the narrowest wall line. Where the wall count changes, the lines go from this width to two times this width. 0 uses 0.85 x the nozzle diameter." },
    .{ .name = "project.min_feature_size", .section = "Walls", .doc = "Arachne: parts thinner than this print nothing. A thicker part that is thinner than a line gets one line of at least `min_bead_width`. 0 uses 1/4 of the line width." },
    .{ .name = "project.min_bead_width", .section = "Walls", .doc = "Arachne: the narrowest line in a part thinner than a line. 0 uses `min_wall_line_width`." },
    .{ .name = "project.wall_transition_length", .section = "Walls", .doc = "Arachne: the length over which one line splits into two, or two join into one, where the wall count changes. 0 uses the line width." },
    .{ .name = "project.wall_transition_angle", .section = "Walls", .doc = "Arachne: in a wedge with a larger angle than this (in degrees), the wall count does not change along the middle: the walls follow the sides, and no line fills the middle." },
    .{ .name = "project.wall_transition_filter_distance", .section = "Walls", .doc = "Arachne: two changes of the wall count closer together than this cancel out, so that the walls do not go back and forth." },
    .{ .name = "project.wall_distribution_count", .section = "Walls", .doc = "Arachne: the number of walls, counted from the middle, that share a change of the line width. 1: only the middle line changes, and the outer walls keep their width." },
    .{ .name = "project.top_thickness", .section = "Top and bottom skin", .doc = "The thickness of solid skin under each top surface." },
    .{ .name = "project.bottom_thickness", .section = "Top and bottom skin", .doc = "The thickness of solid skin above each bottom surface." },
    .{ .name = "project.skin_removal_width", .section = "Top and bottom skin", .doc = "Skin pieces narrower than this are removed before the expand (a sliver of skin at the edge of a slope). A thin piece next to a large skin area still gets skin from the expand." },
    .{ .name = "project.skin_expand_distance", .section = "Top and bottom skin", .doc = "The skin grows this far into the sparse infill next to it, so that its edges hold on the infill and close against the walls." },
    .{ .name = "project.solid_infill_width", .section = "Top and bottom skin", .doc = "A sparse infill area narrower than this prints solid, as skin. A narrow strip would get no infill lines, and a gap would show next to the walls under a top surface." },
    .{ .name = "project.skin_pattern", .section = "Top and bottom skin", .doc = "How the skin is filled. `lines`: parallel lines in the nearest order. `monotonic`: parallel lines from one side to the other, so each line lies against the line before it in the same way; the top has an even sheen. `concentric`: loops that follow the outline." },
    .{ .name = "project.angles_follow_part", .section = "Top and bottom skin", .doc = "The skin and infill lines turn with the part: the turn of a part on the bed adds to `skin_angle` and `infill_angle`, so the lines keep their place on the part. Off: the angles are from the X axis of the bed for each part." },
    .{ .name = "project.skin_angle", .section = "Top and bottom skin", .doc = "The direction of the skin lines on the first layer, in degrees from the X axis. Ironing goes at a right angle to the top skin." },
    .{ .name = "project.skin_angle_step", .section = "Top and bottom skin", .doc = "How much the skin direction turns from one layer to the next, in degrees. 90 crosses the lines of each layer with the layer below." },
    .{ .name = "project.skin_overlap", .section = "Top and bottom skin", .doc = "Skin lines go this far into the walls, as a fraction of the line width, so that the skin bonds to the walls." },
    .{ .name = "project.skin_link_length", .section = "Top and bottom skin", .doc = "Retractless skin: the top and bottom skin of each island prints as few paths as it can. The skin lines split into pieces at holes and corners, and each piece prints as one zigzag. From the end of a zigzag, the nozzle goes on to the next zigzag along the walls, and prints on the way, if that way is at most this long (mm). A travel and a retraction come only where no such way is. The way can go over the line ends of skin that is printed already. It prints at half the line width, as each link of a zigzag does, so it adds no ridge along the wall. The zigzags just below a zigzag print before it, so at a hole both sides fill before the skin over the hole. 0: off, each piece prints on its own. Only for the `lines` pattern." },
    .{ .name = "project.bridges", .section = "Top and bottom skin", .doc = "Print bridges as bridges: the part of a bottom skin over air that solid plastic holds at its sides prints in straight lines across the air (the direction with the most lines that start and end on solid plastic), each line anchored on the solid skin around it, slower (`bridge_speed`), with `bridge_flow` and `bridge_fan`. The parts of the walls over air (1 mm or longer) print as bridges too. Off: the bridge prints as normal skin and walls." },
    .{ .name = "project.bridge_speed", .section = "Top and bottom skin", .doc = "The speed of the bridge lines, as a ratio of the allowed speed. A slow line sags less." },
    .{ .name = "project.bridge_flow", .section = "Top and bottom skin", .doc = "The flow of the bridge lines, as a ratio of the flow of a normal line. A little less flow makes a thinner strand that cools fast." },
    .{ .name = "project.bridge_fan", .section = "Top and bottom skin", .doc = "The fan speed while the bridge lines print, from 0 to 1." },
    .{ .name = "project.path_rules", .section = "Top and bottom skin", .doc = "Rules for each path, one on each line: \"speed = ...\", \"flow = ...\", or \"fan = ...\", with a formula (see the formulas of the settings). The variables of a path: {feature} (\"outer_wall\", \"inner_wall\", \"skin\", \"infill\", \"bridge\", ...), {layer} (from 0), {z} (mm), {part}, {speed} (the planned speed, mm/s), {width} and {height} (mm), {length} (mm), and {fan} (0 to 1). \"speed\" sets the speed in mm/s, \"flow\" multiplies the flow, and \"fan\" sets the fan (0 to 1) while the path prints. For example: speed = {feature} == \"outer_wall\" and {z} < 5 ? 20 : {speed}. A line that does not work is left out." },
    .{ .name = "project.gap_fill", .section = "Top and bottom skin", .doc = "Fill the narrow areas that no wall and no skin line covers (a strip between two walls, a wedge of skin next to a hole) with a line along the middle of each area. The width of the line follows the width of the area. These lines print at the skin speed. A part thinner than one line gets a line from `thin_walls`, not from this setting." },
    .{ .name = "project.infill_density", .section = "Infill", .doc = "The fraction of the inside that the sparse infill fills, as a ratio. 0 makes the part hollow." },
    .{ .name = "project.infill_pattern", .section = "Infill", .doc = "The sparse infill pattern. `lines`: one direction on each layer, turned 90 degrees on the next layer. `grid`: two directions on each layer. `triangles`: three directions at 60 degrees on each layer, which cross at the same points, so they make triangles. `trihexagon`: the three directions of `triangles`, with the third set moved by half its spacing, so the lines make triangles and hexagons (as in Cura). `cubic`: three directions that move with the height, so the infill makes cubes in 3D. `gyroid`: smooth curves that change with the height, strong in all directions. `concentric`: loops that follow the outline. `honeycomb`: hexagon cells, the same on all layers. `zigzag`: the lines of `lines`, joined at the walls into one path, so the nozzle does not travel or retract between them. `flow`: the zigzag, with twice the density under each top surface (a band of 3 times the top thickness, at least 2 mm), where the top skin needs it, and the density of the setting in the middle. `lightning`: thin branches only under the top surfaces; they grow down from each top, join into trees, and end at the walls, so most of the inside stays empty. For display parts: it is fast and uses little plastic, but it is weak. The density sets the distance between the branches under a top." },
    .{ .name = "project.infill_angle", .section = "Infill", .doc = "The angle of the infill and skin lines, in degrees from the X axis." },
    .{ .name = "project.infill_angles", .section = "Infill", .doc = "A list of infill angles in degrees from the X axis, with commas between them, one for each layer in turn: \"45,45,45,135,135,135\" prints 3 layers at 45 degrees, then 3 layers at 135 degrees, and again. The line patterns (lines, zigzag, flow, grid, triangles, trihexagon, cubic, honeycomb) use the angle of the layer in place of `infill_angle`, and the lines and zigzag patterns do not turn by 90 degrees on each layer. Empty: `infill_angle`. As \"Infill Line Directions\" in Cura." },
    .{ .name = "project.infill_stack", .section = "Infill", .doc = "Keep the infill of all layers on top of each other: the lines, zigzag, and flow patterns do not turn by 90 degrees on each layer. The lines of each layer lie on the lines of the layer below, and make vertical walls, for example the openings of a grille. Grid, triangles, trihexagon, honeycomb, and concentric stack in each case. Honeycomb also prints each cell wall once, so all its walls have one width (else two of the six sides of a cell print twice)." },
    .{ .name = "project.infill_anchor", .section = "Infill", .doc = "Where the grid of the sparse infill starts. \"part\": at the center of each part, so a part with two equal sides gets equal infill on both, and the copies of a part get the same infill. \"bed\": at the origin of the bed, as before." },
    .{ .name = "project.infill_flow", .section = "Infill", .doc = "The flow of the sparse infill lines, as a ratio of the flow of a normal line. As \"Infill Flow\" in Cura." },
    .{ .name = "project.infill_connect", .section = "Infill", .doc = "Join the infill lines (lines, grid, triangles, cubic) at their ends with a short line along the edge, as \"Connect Infill Lines\" in Cura: the nozzle prints a zigzag with no travel and no retraction, and the joints tie the infill to the walls. Off: each line on its own." },
    .{ .name = "project.infill_ribs", .section = "Infill", .doc = "A rib in each narrow infill area that the infill lines miss: one line along the length of the area, through its middle, on each layer, so the lines stack into a rib. At a low density the lines are far apart (10 % grid: 11 mm), and an area narrower than that gets no infill on most layers; the top over it then sags. Off: such an area stays empty." },
    .{ .name = "project.lightning_angle", .section = "Infill", .doc = "The lightning infill: how far a branch leans from vertical, in degrees. On each layer down, the end of a branch gets shorter by the layer height times tan(angle), and a bent branch gets straighter by at most the same distance. A larger angle gives smaller trees and less plastic, but the lines hang out more over the layer below." },
    .{ .name = "project.top_support_layers", .section = "Infill", .doc = "Top support: the layers under each top skin that get denser infill lines (one direction on each layer, turned 90 degrees on the next), so that the skin lies on a flat grid and bridges less. 0: off. The flow pattern has its own band." },
    .{ .name = "project.top_support_density", .section = "Infill", .doc = "The density of the top support lines, as a ratio. It works only if it is more than `infill_density`." },
    .{ .name = "project.infill_overlap", .section = "Infill", .doc = "Sparse infill lines go this far into the walls, as a fraction of the line width." },
    .{ .name = "project.infill_layers", .section = "Infill", .doc = "Print the sparse infill once every this many layers, as one taller bead at the top layer of each group, with the flow of all the layers. The walls and the skin still print on each layer. Sparse infill is hidden, so it does not need the fine layers, and the print has fewer infill moves. A group is never thicker than the diameter or the line width of the nozzle of the infill (see `infill_filament`): the count goes down where the layers are too thick, and the Check tells it. Only the area that is sparse infill in all layers of a group gets the tall bead, and the dense band under the top skin prints on each layer. 1: each layer." },
    .{ .name = "project.ironing", .section = "Ironing", .doc = "Iron the top surfaces. After the layer is complete, the nozzle goes over each top surface again with close lines and a small flow. The hot nozzle melts the surface flat, and the small flow fills the gaps between the skin lines." },
    .{ .name = "project.ironing_flow", .section = "Ironing", .doc = "The flow of the ironing lines, as a ratio of the flow of a normal line." },
    .{ .name = "project.ironing_spacing", .section = "Ironing", .doc = "The distance between the ironing lines." },
    .{ .name = "project.ironing_inset", .section = "Ironing", .doc = "The ironing area is this far inside the edges of the top surface, so that the nozzle does not push plastic over the edges." },
    .{ .name = "project.ironing_speed", .section = "Ironing", .doc = "The ironing speed, as a ratio of `machine.max_speed`. The flow limit of the filament does not apply, because the flow is small." },
    .{ .name = "project.slope_smoothing", .section = "Slope smoothing", .doc = "Fill the steps on gently sloped top surfaces. After each layer, the nozzle goes back along the edge of the layer, over the narrow ledge of the layer below. It lays a bead in the corner of each step, with the volume of the triangle there. The nozzle height can change along the bead, between the two layers." },
    .{ .name = "project.slope_smoothing_min_width", .section = "Slope smoothing", .doc = "The narrowest ledge that gets a bead, as a ratio of the line width. A narrower step is small, and its bead is too small to meter." },
    .{ .name = "project.slope_smoothing_max_width", .section = "Slope smoothing", .doc = "The widest ledge that gets a bead, as a ratio of the line width. A wider ledge is a flat top, or needs more than one bead." },
    .{ .name = "project.slope_smoothing_flow", .section = "Slope smoothing", .doc = "The plastic of a smoothing bead, as a ratio of the volume of the triangle in the step." },
    .{ .name = "project.slope_smoothing_speed", .section = "Slope smoothing", .doc = "The speed of the smoothing beads, as a ratio of the allowed speed." },
    .{ .name = "project.slope_ironing", .section = "Slope smoothing", .doc = "Iron the sloped steps. After each layer (and after its smoothing beads), the nozzle goes along the same ledges as slope smoothing, with a very small flow. At each point, the nozzle tip is at the height of the filled step there, so the hot tip makes the bead tops flat. The ledges are the ones of `slope_smoothing_min_width` and `slope_smoothing_max_width`." },
    .{ .name = "project.slope_ironing_passes", .section = "Slope smoothing", .doc = "The number of ironing passes over each ledge, evenly across it." },
    .{ .name = "project.slope_ironing_flow", .section = "Slope smoothing", .doc = "The flow of the slope ironing lines, as a ratio of the flow of a normal line." },
    .{ .name = "project.slope_ironing_speed", .section = "Slope smoothing", .doc = "The slope ironing speed, as a ratio of `machine.max_speed`. The flow limit of the filament does not apply, because the flow is small." },
    .{ .name = "project.outer_wall_speed", .section = "Speed ratios", .doc = "The outer wall speed, as a ratio of the allowed speed. A slower outer wall gives a better surface." },
    .{ .name = "project.inner_wall_speed", .section = "Speed ratios", .doc = "The inner wall speed, as a ratio of the allowed speed." },
    .{ .name = "project.skin_speed", .section = "Speed ratios", .doc = "The skin speed, as a ratio of the allowed speed." },
    .{ .name = "project.infill_speed", .section = "Speed ratios", .doc = "The sparse infill speed, as a ratio of the allowed speed." },
    .{ .name = "project.support_speed", .section = "Speed ratios", .doc = "The speed of the support lines, as a ratio of the allowed speed. 0: `infill_speed`. As \"Support Infill Speed\" in Cura and \"Support\" speed in OrcaSlicer." },
    .{ .name = "project.support_interface_speed", .section = "Speed ratios", .doc = "The speed of the support interface, as a ratio of the allowed speed. 0: `skin_speed`. As \"Support Interface Speed\" in Cura and \"Support interface\" speed in OrcaSlicer." },
    .{ .name = "project.first_layer_speed", .section = "Speed ratios", .doc = "The speed of all lines on the first layer, as a ratio of the allowed speed." },
    .{ .name = "project.slow_layers", .section = "Speed ratios", .doc = "The layers after the first that print slower: their speed goes up in even steps from the first layer speed to the full speed, so that the part bonds to the bed. 0: the second layer prints at full speed." },
    .{ .name = "project.combing_mode", .section = "Travel", .doc = "Combing: a travel move that stays inside the part (it crosses no outline of the layer) does not retract, because an ooze there is inside the part. The mode sets where the way can go, as the combing modes of Cura. `all`: anywhere in the part. `not_in_skin`: not over the top and bottom skin of the layer. `not_on_top`: not over the top surfaces (the area that no layer covers above). `within_infill`: only in the sparse infill. `off`: each travel longer than `retract_min_travel` retracts. A travel with no way in its area retracts, and lifts with `z_hop`." },
    .{ .name = "project.combing_max_distance", .section = "Travel", .doc = "A travel inside the part that is longer than this retracts all the same (a long move can ooze a string over a top surface). 0: no limit." },
    .{ .name = "project.outer_wall_wipe", .section = "Travel", .doc = "After a closed outer wall, the nozzle moves on along the start of the wall for this distance (mm), with no plastic, before the retraction. The end of the wall then joins its start with no gap, and the seam shows less. 0 turns it off." },
    .{ .name = "project.coasting_volume", .section = "Travel", .doc = "Coasting: the last part of each path moves with no plastic, for this volume of plastic (mm³). The pressure in the nozzle prints it, so the end of the path has less of a blob, and the travel after it strings less. A path shorter than twice this volume prints as usual. 0 turns it off. Cura uses 0.064." },
    .{ .name = "project.coasting_speed", .section = "Travel", .doc = "The speed of the coasting moves, as a ratio of the speed of the path." },
    .{ .name = "project.support", .section = "Support", .doc = "Support under overhangs. `off`: no support. `everywhere`: support can stand on the bed or on the part. `buildplate`: only support that stands on the bed." },
    .{ .name = "project.support_style", .section = "Support", .doc = "The shape of the support. `grid`: all the space under each overhang, filled with lines. `tree`: branches from points under each overhang down to the bed or the part; they join on the way, get thicker as they go down, and thinner in narrow spaces (so a branch can go down a deep, narrow hole). Each branch prints as one wall loop, with lines only at its foot and under its tip. A tree uses less plastic and comes off more easily. `bridge`: only a sacrificial pad under each overhang (the interface layers, with the Z gap over it), with nothing under the pad. The pad bridges from the part around it, as a bridge does, and breaks off easily. For overhangs over a hole or a short gap, where a column down to the bed would be a waste." },
    .{ .name = "project.support_tree_angle", .section = "Support", .doc = "Tree support: the largest angle of a branch from vertical, in degrees. A larger angle lets branches reach farther, with less strength." },
    .{ .name = "project.support_tree_spacing", .section = "Support", .doc = "Tree support: the distance of the tips under an overhang. Tips also go along the edges of each overhang, at the same distance." },
    .{ .name = "project.support_tree_tip", .section = "Support", .doc = "Tree support: the diameter of a tip. 0 uses the line width times 2." },
    .{ .name = "project.support_angle", .section = "Support", .doc = "An overhang that leans more than this angle (degrees) from vertical gets support. A larger angle gives less support." },
    .{ .name = "project.support_min_ledge", .section = "Support", .doc = "No support under a small ledge: a strip of overhang that is within this distance (mm) of the layer below at each point, with no new overhang on the layer above next to it (for example the underside of an embossed letter on a wall). The nozzle prints it as a short cantilever. A slope keeps its support: each layer of it adds a new strip. 0: 1.5 line widths. A tiny value (0.01) turns the rule off." },
    .{ .name = "project.support_density", .section = "Support", .doc = "The fraction of the support area that the support lines fill, as a ratio." },
    .{ .name = "project.support_xy_gap", .section = "Support", .doc = "The gap between the support and the sides of the part. Under an overhang, the gap is at most half a line width: the Z gap keeps the support off the overhang there." },
    .{ .name = "project.support_z_gap_layers", .section = "Support", .doc = "The number of empty layers between the support and the part above it or under it, so that the support comes off." },
    .{ .name = "project.support_interface_layers", .section = "Support", .doc = "The number of dense layers at the top of the support, under the part. They make the bottom surface of the part smooth." },
    .{ .name = "project.support_interface_density", .section = "Support", .doc = "The fraction of the interface area that its lines fill, as a ratio." },
    .{ .name = "project.support_interface_pattern", .section = "Support", .doc = "The pattern of the support interface. `lines`: parallel lines. `grid`: lines in two directions, a flatter bed for the part. `dots`: the lines cut into short dabs, in rows that shift on each layer: little contact with the part, so the support breaks off easily and leaves a cleaner surface." },
    .{ .name = "project.skirt_loops", .section = "Skirt and brim", .doc = "The number of skirt loops. A skirt is a loop around the part on the first layers, at a distance from it. It primes the nozzle before the part starts. 0 turns it off." },
    .{ .name = "project.skirt_distance", .section = "Skirt and brim", .doc = "The distance from the part (or from the brim) to the skirt." },
    .{ .name = "project.skirt_layers", .section = "Skirt and brim", .doc = "The number of layers with a skirt." },
    .{ .name = "project.brim_width", .section = "Skirt and brim", .doc = "The width of the brim. A brim is loops on the first layer around the outside of the part, joined to it. It holds the part on the bed, and helps against warping. 0 turns it off." },
    .{ .name = "project.brim_location", .section = "Skirt and brim", .doc = "Where the brim goes. `outside`: around the outside of the part. `inside`: in the holes of the part, along their edges. `everywhere`: both." },
    .{ .name = "project.first_layer_xy_offset", .section = "First layer", .doc = "Moves the outline of the first layer by this distance. A negative value compensates the \"elephant foot\": the first layer spreads out because the nozzle presses it on the bed." },
    .{ .name = "project.placement", .section = "Placement", .doc = "Where the part goes on the bed. auto: at the X and Y of the file if the part is fully on the bed there, else at the center of the bed; a model added to a plate with parts gets smart placement (its best orientation, then a free spot), and the parts on the plate stay. file: always at the X and Y of the file. center: always at the center of the bed. The bottom of the part always goes to z = 0." },
    .{ .name = "project.print_sequence", .section = "Placement", .doc = "The order of the parts of the plate. `by_layer`: each layer of all parts, then the next layer. `by_object`: one part from the bottom to the top, then the next part, in the order of the plate list. Between the parts, the head goes up over the printed parts. The parts must keep `machine.clearance_radius` from each other, and only the last part can be higher than `machine.clearance_height` (the Check lists each problem). A part that fails then stops only itself, and a part has no strings to the others. No prime tower." },
    .{ .name = "project.resolution", .section = "Outlines", .doc = "The largest change to the shape (mm) that the slicer makes when it removes points from the mesh outlines. A larger value gives fewer points and a faster slice, and changes the G-code: 0.01 slices a 3DBenchy about 19 % faster, and moves its outer walls up to 10 µm. The name before: `engine.resolution`." },
    .{ .name = "project.fast_offsets", .section = "Experimental", .doc = "An experiment: a faster offset of the outlines. A closing corner of an offset gets the crossing point of its two edges in place of a small loop that a union then removes. A slice uses about 11 % less CPU. The outer walls stay within about 1.4 micrometers; some skin and fill lines move more than that where a thin piece is at a threshold, so a thin piece of skin can come or go. Off: the offsets of before, and the same G-code. The switch is for the whole app: the last slice that starts sets it." },
    .{ .name = "project.filament", .section = "Filaments", .doc = "The filament that prints this part, or these layers: 1 is the first filament of the plate, 2 the second, and so on. A change at a layer is a filament change in the G-code." },
    .{ .name = "project.support_filament", .section = "Filaments", .doc = "The filament of the support: 1 is the first filament of the plate, 2 the second, and so on. 0: the filament of the part. A filament for support only (one that breaks away, or one that dissolves in water) makes support easy to take off. On a printer with more than one nozzle, the support prints with the nozzle of that filament." },
    .{ .name = "project.support_interface_filament", .section = "Filaments", .doc = "The filament of the support interface (the layers that touch the part). 0: the support filament." },
    .{ .name = "project.infill_filament", .section = "Filaments", .doc = "The filament of the sparse infill: 1 is the first filament of the plate, 2 the second, and so on. 0: the filament of the part. On a printer with more than one nozzle, a filament of another nozzle prints the infill with that nozzle, at its line width. With combined infill (`infill_layers` above 1), this filament prints only the tall beads, and the filament of the part prints the narrow areas of infill that print on each layer: the nozzle then changes once in each group of layers." },
    .{ .name = "project.prime_tower", .section = "Filaments", .doc = "A prime tower for a printer that changes the filament with a tool change (`machine.filament_change = tool`): after each change, the nozzle flushes the old color out into a small tower next to the parts, and wipes there, before the new filament touches the part. The tower grows on each layer up to the last change (its wall, a solid base under the next prime, and sparse lines), so it is at the height of the nozzle at each change. A Bambu Lab printer flushes into its chute (its change G-code); its tower then gets a prime of 45 mm³ of the new filament." },
    .{ .name = "project.prime_tower_split", .section = "Filaments", .doc = "A prime tower for each family of materials that bond (PLA, PETG, ABS and ASA, and the others): a change purges into the tower of the new filament, so PETG never purges on PLA. Each tower grows on each layer up to its last change; on a layer with no filament of its family, its wall and its inside print with the filament in the nozzle. With one family, one tower." },
    .{ .name = "project.prime_tower_width", .section = "Filaments", .doc = "The width of the square prime tower." },
    .{ .name = "project.prime_tower_brim", .section = "Filaments", .doc = "The brim of the prime tower (mm): loops around the first layer of the tower, so it holds to the bed. 0: no brim." },
    .{ .name = "project.prime_tower_wall_loops", .section = "Filaments", .doc = "The loops of the wall of the prime tower. The rows of each prime end on the inner loop. More loops make a stiffer tower that holds to the bed better, and use more plastic." },
    .{ .name = "project.prime_tower_rib_wall", .section = "Filaments", .doc = "Ribs at the four corners of the prime tower: two strips along its diagonals stick out at the corners, so the wall has a wavy outline and the tower is stiff. As the rib wall of Bambu Studio. Off: a square wall." },
    .{ .name = "project.prime_tower_rib_width", .section = "Filaments", .doc = "The width of a rib of the prime tower (mm), at most half the side of the tower." },
    .{ .name = "project.prime_tower_extra_rib_length", .section = "Filaments", .doc = "The length of the ribs of the prime tower past its diagonal on the bed (mm). The extra length gets less on each layer, to 0 at the top. The ribs are never shorter than the diagonal." },
    .{ .name = "project.prime_tower_fillet_wall", .section = "Filaments", .doc = "Round corners on the wall of a prime tower with ribs." },
    .{ .name = "project.prime_tower_x", .section = "Filaments", .doc = "The x of the center of the prime tower on the bed. -1: near the right side." },
    .{ .name = "project.prime_tower_y", .section = "Filaments", .doc = "The y of the center of the prime tower. -1: near the back." },
    .{ .name = "project.flush_multiplier", .section = "Filaments", .doc = "A multiplier for the flush volume of each filament change (see `machine.flush_volume`). Lower wastes less plastic. Too low mixes the old color into the new one." },
    .{ .name = "project.flush_into_hidden", .section = "Filaments", .doc = "After a change to a filament, the nozzle first prints the hidden lines of that filament on the layer: its sparse infill and its support body. The old color goes into them, so the flush of the change is less by their volume. A change between two families of materials (see `prime_tower_split`) flushes into the support body only. The walls and the skin print after." },
    .{ .name = "project.paint_anchor_depth", .section = "Filaments", .doc = "A painted feature that stands on the part, for example a raised letter or frame in another filament, grows down into the part by this depth (mm). This hidden root of its filament replaces the infill of the part under the feature, so the feature holds to the part. The root stays inside the walls of the part: the outside of the part keeps its color. Each layer of the root adds a filament change. 0: no root." },
    .{ .name = "project.paint_anchor_shape", .section = "Filaments", .doc = "The shape of the root of a painted feature (see `paint_anchor_depth`). `footprint`: all the area where the feature stands on the part, inside the walls of the part. `core`: only the middle of that area, inside the walls of the feature. A thin feature gets no core." },
    .{ .name = "engine.gap_closing", .section = "Slicer", .doc = "The largest gap (mm) that the slicer closes in a mesh with holes." },
    .{ .name = "engine.threads", .section = "Slicer", .doc = "The number of threads. 0 uses one thread for each CPU but one, so that the app and the desktop can answer while a slice runs." },
    .{ .name = "engine.draft_slices", .section = "Slicer", .doc = "A draft slice for the view during an edit: the outlines lose the points within 0.05 mm of a straight line, the gaps get no fill, and the walls are classic walls. A draft needs about a third of the time of the exact slice, and the exact slice follows it. A draft never goes to the G-code. Off: each edit gives the exact slice only." },
    .{ .name = "engine.auto_simulate", .section = "Slicer", .doc = "The print as it forms: a simulation of the plastic after each exact slice. Off saves the CPU of the run (about 0.4 s for a 3DBenchy), and the Check shows no simulated failures until you run the simulation by hand (\"Show the print as it forms\"). The G-code is the same." },
    .{ .name = "engine.slice_form", .section = "Slicer", .doc = "Keep the work of a slice for each part and each level, and make only the changed pieces again. The G-code is the same. Off: the slicer keeps its work as before." },
    .{ .name = "engine.verify_slices", .section = "Slicer", .doc = "After each slice that used kept work, slice again from the start and compare the G-code. For tests. It doubles the time of a slice." },
    .{ .name = "engine.form_budget_mb", .section = "Slicer", .doc = "The most memory, in MB, of the kept work that only makes the next slice faster. The web app uses at most 96." },
    .{ .name = "engine.job_name", .section = "Slicer", .doc = "The name of the print, for {job_name} in the start and end G-code. The command line tool sets it to the model file name." },
    .{ .name = "machine.nozzle.k.diameter", .section = "Other nozzles", .doc = "The diameter of this nozzle, in mm. 0: `nozzle_diameter`. With the automatic line width (`project.line_width = 0`), its lines are 1.1 times this wide." },
    .{ .name = "machine.nozzle.k.line_width", .section = "Other nozzles", .doc = "The line width of the walls, the skin, and the infill of this nozzle, in mm. 0: the line width of the first nozzle, times `diameter` / `nozzle_diameter`. The first layer gets the same ratio to its own width." },
    .{ .name = "machine.nozzle.k.speed", .section = "Other nozzles", .doc = "The speed of the lines of this nozzle, as a ratio of the speed that the same line gets on the first nozzle. The ratios of the features to each other stay. 0: the same speeds. Travel moves keep `travel_speed`." },
    .{ .name = "machine.nozzle.k.max_speed", .section = "Other nozzles", .doc = "The highest speed of the lines of this nozzle, in mm/s, after `speed`. 0: no limit of its own. A Bambu Lab X2D prints with its second nozzle (a bowden extruder) at most at 200 mm/s." },
    .{ .name = "machine.nozzle.k.max_accel", .section = "Other nozzles", .doc = "The highest acceleration of the lines of this nozzle, in mm/s². 0: no limit of its own. The G-code has it only with `accel_control`; the time estimate always uses it." },
    .{ .name = "machine.nozzle.k.retract_length", .section = "Other nozzles", .doc = "The retraction length of this nozzle, in mm. 0: `retract_length`. The X2D feeds its second nozzle through a bowden tube: Bambu Studio retracts 2 mm there and 0.8 mm on the first." },
    .{ .name = "machine.nozzle.k.retract_speed", .section = "Other nozzles", .doc = "The speed of the filament in a retraction of this nozzle, in mm/s. 0: `retract_speed`." },
    .{ .name = "machine.nozzle.k.offset_x", .section = "Other nozzles", .doc = "The position of this nozzle from the first nozzle in X, in mm, when the firmware does not correct it (the tool offset). The G-code moves the head by minus this offset for the lines and the travels of this nozzle. As extruder_offset in PrusaSlicer. 0: the firmware corrects the offset (Prusa XL, Bambu Lab X2D, Klipper tool changers with offsets in printer.cfg)." },
    .{ .name = "machine.nozzle.k.offset_y", .section = "Other nozzles", .doc = "The position of this nozzle from the first nozzle in Y, in mm. See `offset_x`." },
    .{ .name = "machine.nozzle.k.min_x", .section = "Other nozzles", .doc = "The left edge of the area that this nozzle reaches, in bed X (mm). The second nozzle of the X2D stops 20.5 mm from the left side of the bed. 0: the left side of the bed." },
    .{ .name = "machine.nozzle.k.max_x", .section = "Other nozzles", .doc = "The right edge of the area that this nozzle reaches, in bed X (mm). 0: the right side of the bed." },
    .{ .name = "machine.nozzle.k.max_height", .section = "Other nozzles", .doc = "The highest z that this nozzle reaches (mm). 0: `max_height`." },
    .{ .name = "machine.nozzle.k.standby_delta", .section = "Other nozzles", .doc = "The temperature change of this nozzle while it waits, in °C. 0: `standby_delta`." },
    .{ .name = "machine.nozzle.k.preheat_time", .section = "Other nozzles", .doc = "The time before a change to this nozzle at which it heats, in seconds. 0: `preheat_time`." },
};
